using AfriWallet.Merchants.Settlement.Application.Abstractions;using AfriWallet.Merchants.Settlement.Application.Commands;using AfriWallet.Merchants.Settlement.Application.Policies;using AfriWallet.Merchants.Settlement.Application.Results;using AfriWallet.Merchants.Settlement.Domain.Settlements;
namespace AfriWallet.Merchants.Settlement.Application.Services;
public sealed class MerchantSettlementService(IMerchantSettlementRepository repo,ICaptureEligibleDecisionReader decisions,IMerchantSettlementProvider provider,IMerchantSettlementAuditStore audit,IMerchantSettlementClock clock,MerchantSettlementRoutingPolicy routing,MerchantSettlementRetryPolicy retry){
 public async Task<MerchantSettlementResult>CreateAsync(CreateMerchantSettlementCommand c,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(c.IdempotencyKey)||string.IsNullOrWhiteSpace(c.Actor))throw new ArgumentException("Idempotency key and actor are required.",nameof(c));var existing=await repo.GetByIdempotencyKeyAsync(c.IdempotencyKey,ct)??await repo.GetByDecisionAsync(c.PaymentDecisionId,ct);if(existing is not null)return Map(existing);var d=await decisions.GetAsync(c.PaymentDecisionId,ct)??throw new KeyNotFoundException("Payment decision not found.");routing.EnsureEligible(d,c.Route);var s=new MerchantSettlementOrchestration(Guid.NewGuid(),d.DecisionId,d.PaymentIntentId,d.MerchantId,c.Route,d.AmountMinor,d.Currency,c.IdempotencyKey,clock.UtcNow);await repo.AddAsync(s,ct);await Audit(s,"settlement.created",c.Actor,ct);return Map(s);}
 public async Task<MerchantSettlementResult>DispatchAsync(DispatchMerchantSettlementCommand c,CancellationToken ct=default){var s=await Required(c.SettlementId,ct);if(s.Status!=MerchantSettlementStatus.Created)throw new InvalidOperationException("Settlement must be freshly created to dispatch.");await Submit(s,c.Actor,ct);return Map(s);}public async Task<MerchantSettlementResult>RetryAsync(RetryMerchantSettlementCommand c,CancellationToken ct=default){var s=await Required(c.SettlementId,ct);if(s.Status!=MerchantSettlementStatus.RetryPending)throw new InvalidOperationException("Settlement is not pending retry.");await Submit(s,c.Actor,ct);return Map(s);}
 public async Task<MerchantSettlementResult>CompensateAsync(CompensateMerchantSettlementCommand c,CancellationToken ct=default){var s=await Required(c.SettlementId,ct);if(s.Status!=MerchantSettlementStatus.CompensationRequired||string.IsNullOrWhiteSpace(s.ProviderReference))throw new InvalidOperationException("Settlement does not require compensable provider reference.");if(await provider.CompensateAsync(s.ProviderReference,ct)){s.CompleteCompensation(clock.UtcNow);await Audit(s,"settlement.compensated",c.Actor,ct);}else{s.RequireManualIntervention(MerchantSettlementReasonCode.ManualInterventionRequired,clock.UtcNow);await Audit(s,"settlement.manual_intervention_required",c.Actor,ct);}await repo.SaveAsync(s,ct);return Map(s);}public async Task<MerchantSettlementResult>CompleteAsync(CompleteMerchantSettlementCommand c,CancellationToken ct=default){var s=await Required(c.SettlementId,ct);s.Complete(clock.UtcNow);await repo.SaveAsync(s,ct);await Audit(s,"settlement.completed",c.Actor,ct);return Map(s);}public async Task<MerchantSettlementResult>GetAsync(Guid id,CancellationToken ct=default)=>Map(await Required(id,ct));
 private async Task Submit(MerchantSettlementOrchestration s,string actor,CancellationToken ct){var correlation=Guid.NewGuid().ToString("N");s.MarkDispatchPending(correlation,clock.UtcNow);var r=await provider.SubmitAsync(new(s.SettlementId,s.PaymentDecisionId,s.PaymentIntentId,s.MerchantId,s.Route,s.AmountMinor,s.Currency,s.IdempotencyKey,correlation),ct);s.RecordAttempt(r.ProviderReference,r.Status.ToString(),clock.UtcNow);string eventType;switch(r.Status){case MerchantSettlementProviderStatus.Accepted:s.Acknowledge(r.ProviderReference,clock.UtcNow);eventType="settlement.acknowledged";break;case MerchantSettlementProviderStatus.PartialFailure:s.RequireCompensation("Partial sandbox provider processing.",r.ProviderReference,clock.UtcNow);eventType="settlement.compensation_required";break;case MerchantSettlementProviderStatus.Timeout:case MerchantSettlementProviderStatus.TemporaryFailure:if(retry.ShouldRetry(r.Status,s.AttemptCount)){s.ScheduleRetry(r.Status==MerchantSettlementProviderStatus.Timeout?MerchantSettlementReasonCode.ProviderTimeout:MerchantSettlementReasonCode.ProviderTemporaryFailure,clock.UtcNow);eventType="settlement.retry_scheduled";}else{s.RequireManualIntervention(MerchantSettlementReasonCode.RetryExhausted,clock.UtcNow);eventType="settlement.manual_intervention_required";}break;default:s.Fail(MerchantSettlementReasonCode.ProviderPermanentFailure,clock.UtcNow);eventType="settlement.failed";break;}await repo.SaveAsync(s,ct);await Audit(s,eventType,actor,ct);}
 private async Task<MerchantSettlementOrchestration>Required(Guid id,CancellationToken ct)=>await repo.GetAsync(id,ct)??throw new KeyNotFoundException("Merchant settlement not found.");private async Task Audit(MerchantSettlementOrchestration s,string type,string actor,CancellationToken ct)=>await audit.AppendAsync(new(Guid.NewGuid(),s.SettlementId,s.PaymentDecisionId,s.MerchantId,type,actor,clock.UtcNow,new Dictionary<string,string>{{"route",s.Route.ToString()},{"status",s.Status.ToString()},{"reasonCode",s.ReasonCode.ToString()},{"attemptCount",s.AttemptCount.ToString()},{"realCapturePerformed","false"},{"realSettlementPerformed","false"},{"realPayoutPerformed","false"},{"merchantFundsMoved","false"},{"walletBalanceMutated","false"},{"directLedgerMutationPerformed","false"},{"externalSettlementPerformed","false"}}),ct);private static MerchantSettlementResult Map(MerchantSettlementOrchestration s)=>new(s.SettlementId,s.PaymentDecisionId,s.PaymentIntentId,s.MerchantId,s.Route,s.AmountMinor,s.Currency,s.Status,s.ReasonCode,s.IdempotencyKey,s.CorrelationId,s.ProviderReference,s.AttemptCount,s.Compensations.Count,s.CreatedAtUtc,s.UpdatedAtUtc);}
